"""Renal dosing for the 61 entries previously built from the Renal Drug Handbook (5th ed.),
rebuilt from current product labels: US FDA labels (DailyMed/openFDA) and, where no US product
exists, UK SmPCs (emc). Each statement paraphrases the cited label; nothing is carried over
from the handbook. Label metadata is in label_meta_v120.json.
"""

def T(indication, rows):
    return dict(indication=indication, rows=[dict(context=c, dose=d) for c, d in rows])

def M(status, tables=None, notes=''):
    return dict(status=status, tables=tables or [], notes=notes)

NC = 'The selected label gives no dialysis or kidney-replacement dosing for this setting. Not curated; consult renal pharmacy.'
SILENT = 'The selected label gives no renal-impairment dosing statement.'

def entry(metric, summary, flag, formulation, ckd, ihd=None, pd=None, crrt=None, considerations=''):
    return dict(kidneyMetric=metric, summary=summary, flag=flag, formulation=formulation, ckd=ckd,
                ihd=ihd or M('not_curated', notes=NC), pd=pd or M('not_curated', notes=NC),
                crrt=crrt or M('not_curated', notes=NC), considerations=considerations)

